// The backend posts the checked minutes and the meeting's distribution list (the
// administrators edit the lists in Liminal); this node turns them into one email.
const b = $input.first().json.body;
const m = b.minutes || {};
const LISTS = { medical: "Medical board", executive: "Executive board", administrative: "Administrative board" };
if (!LISTS[m.meeting_type]) {
  // an unknown tag must not look like a delivery: the backend then mails directly
  throw new Error(`unknown meeting type: ${m.meeting_type}`);
}
// one line only: a title must never add a header to the email
const title = String(m.title || "").split(/[\r\n]+/).join(" ").trim();
const to = (b.distributionList || []).filter((a) => /^[^\s@<>,;]+@[^\s@<>,;]+$/.test(a));
if (!to.length) throw new Error("no distribution list for this meeting");
const lines = [title, "", m.summary || "", ""];
if ((m.decisions || []).length) {
  lines.push("Decisions:");
  m.decisions.forEach((d, i) => lines.push(`  ${i + 1}. ${d}`));
  lines.push("");
}
if ((m.action_items || []).length) {
  lines.push("Action items:");
  m.action_items.forEach((a, i) => lines.push(`  ${i + 1}. ${a.text} | ${a.owner || "owner not set"} | ${a.deadline || "no deadline set"}`));
  lines.push("");
}
lines.push("The minutes in Romanian, Russian and English are attached (PDF/A).");
lines.push("Drafted by Liminal on the hospital's own server; every item was checked against the recording.");
const binary = {};
(b.documents || []).forEach((d, i) => {
  binary[`doc${i}`] = { data: d.data, mimeType: d.mimeType || "application/pdf", fileName: d.fileName };
});
return [{
  json: {
    meetingId: b.meetingId,
    meetingType: m.meeting_type,
    subject: `MoM | ${LISTS[m.meeting_type].replace(" board", "")} | ${title}`,
    to: to.join(", "),
    text: lines.join("\n"),
    cc: (b.participant_emails || []).join(","),
    attachments: Object.keys(binary).join(","),
  },
  binary,
}];
